import {C,facilityTypes as F,trashTypes as T} from './config.js';
export class Renderer{
 constructor(canvas){this.canvas=canvas;this.ctx=canvas.getContext('2d');this.view={scale:1,x:0,y:0}}
 point(e){let r=this.canvas.getBoundingClientRect(),v=this.view;return{x:Math.floor((e.clientX-r.left-v.x)/v.scale),y:Math.floor((e.clientY-r.top-v.y)/v.scale)}}
 draw(g,selected,mode){const c=this.canvas,r=c.getBoundingClientRect(),d=Math.min(devicePixelRatio||1,2);if(c.width!==Math.round(r.width*d)||c.height!==Math.round(r.height*d)){c.width=Math.round(r.width*d);c.height=Math.round(r.height*d)}let ctx=this.ctx,s=Math.min(r.width/24,r.height/14),ox=(r.width-24*s)/2,oy=(r.height-14*s)/2;this.view={scale:s,x:ox,y:oy};ctx.setTransform(d,0,0,d,0,0);ctx.fillStyle='#233c38';ctx.fillRect(0,0,r.width,r.height);ctx.translate(ox,oy);ctx.scale(s,s);const box=(x,y,w,h,col)=>{ctx.fillStyle=col;ctx.fillRect(x,y,w,h)},text=(t,x,y,size=.3,col='#f3f5dc',align='left')=>{ctx.font=`600 ${size}px system-ui`;ctx.textAlign=align;ctx.fillStyle=col;ctx.fillText(t,x,y)};
 for(let y=0;y<14;y++)for(let x=0;x<24;x++)box(x+.025,y+.025,.95,.95,y>=g.land?'#162d2b':(x+y)%2?'#3c5546':'#405b49');box(0,0,24,2.2,'#344d4c');for(let x=1;x<24;x+=3){box(x,.4,1.6,1.6,'#607669');box(x+.2,.7,.35,.4,'#b2c3a0');box(x+.9,.7,.35,.4,'#b2c3a0')}text('まちへ、もう一度。',12,1.6,.35,'#e1d9af','center');box(0,2.3,24,1.8,'#303c42');for(let x=0;x<24;x+=2)box(x,3.12,.9,.07,'#e6d99d');box(2,4,19,.1,'#f2cf69');text('←  回収可能区間  →',11.5,4.65,.27,'#f3d97f','center');if(g.land<14)text('土地拡張で使える区画',12,12.7,.4,'#789384','center');
 if(selected?.kind==='oni'){const o=g.onis.find(o=>o.id===selected.id);if(o){ctx.strokeStyle='#f5da76';ctx.lineWidth=.1;ctx.beginPath();ctx.moveTo(o.x+.5,o.y+.5);for(const p of o.path)ctx.lineTo(p.x+.5,p.y+.5);ctx.stroke()}}
 for(const f of g.facilities){let color=F[f.type].color;box(f.x+.08,f.y+.18,1.9,1.9,'#20312d');box(f.x,f.y,1.85,1.7,color);box(f.x+.15,f.y+.42,1.55,.78,'#243c3e');text(F[f.type].name,f.x+.92,f.y+.95,.4,'#f7f2dd','center');text(`Lv${f.level} · ${f.input.length}/${g.capacity(f)}`,f.x+.92,f.y+1.49,.26,'#172b2d','center');box(f.x+.23,f.y-.18,.55,.2,'#e8d58a');if(f.jobs.length){box(f.x+.12,f.y+.08,1.6,.13,'#1b3635');box(f.x+.12,f.y+.08,1.6*Math.min(1,f.jobs[0].progress),.13,'#fff6c9')}if(f.output.length)text(`待 ${f.output.length}`,f.x+1,f.y+2.15,.28,'#f8dc76','center');if(selected?.kind==='facility'&&selected.id===f.id){ctx.strokeStyle='#fff5a2';ctx.lineWidth=.08;ctx.strokeRect(f.x-.1,f.y-.2,2.1,2.1)}if(g.synergy(f)>1)text('連携',f.x+1.9,f.y+.05,.23,'#f8ee95','right')}
 for(const t of g.trucks){box(t.x,2.5,2.2,1.1,'#9cb881');box(t.x+1.7,2.7,.7,.9,'#e6c86d');box(t.x+1.88,2.76,.4,.36,'#365557');box(t.x+.25,3.48,.4,.25,'#15292d');box(t.x+1.7,3.48,.4,.25,'#15292d');text(`♻ ${t.items.length}`,t.x+.8,3.21,.4,'#193730','center');t.items.slice(0,7).forEach((it,i)=>box(t.x+.12+i*.21,2.56,.16,.14,T[it.type].color))}
 for(const o of g.onis){const x=o.x+.5,y=o.y+.5;ctx.fillStyle=F[o.type].color;ctx.beginPath();ctx.arc(x,y,.23,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.moveTo(x-.2,y-.13);ctx.lineTo(x-.18,y-.4);ctx.lineTo(x-.05,y-.2);ctx.moveTo(x+.2,y-.13);ctx.lineTo(x+.18,y-.4);ctx.lineTo(x+.05,y-.2);ctx.fill();box(x-.12,y-.06,.05,.06,'#13282c');box(x+.08,y-.06,.05,.06,'#13282c');box(x-.14,y+.24,.09,.13,'#23332d');box(x+.05,y+.24,.09,.13,'#23332d');if(o.carry){box(x+.12,y+.05,.27,.3,T[o.carry.type].color);text(T[o.carry.type].mark,x+.25,y+.27,.2,'#182c31','center')}if(o.stamina<25)text(o.rest?'休':'汗',x,y-.5,.28,'#a9dff0','center');if(selected?.kind==='oni'&&selected.id===o.id){ctx.strokeStyle='#fff0a0';ctx.lineWidth=.07;ctx.beginPath();ctx.arc(x,y,.43,0,Math.PI*2);ctx.stroke()}}
 for(const e of g.effects)text(e.text,e.x+1,e.y,.4,e.text.startsWith('+')?'#ffe782':'#f3eac6','center');if(mode)text('空きマスをタップして配置',12,13.65,.35,'#ffe27c','center');if(g.shout>0){ctx.strokeStyle='#f9d96e';ctx.lineWidth=.16;ctx.strokeRect(.1,.1,23.8,13.8)}if(g.weather!=='normal'&&g.state==='wave')text(g.weather==='rain'?'╱  ╱  ╱  豪雨  ╱  ╱  ╱':g.weather==='storm'?'≋ 嵐・災害ごみ増加 ≋':'☀ 猛暑',12,5.3,.34,'#ffe2a3','center')
 }
}
